  --question \"what did the spaced-repetition model find about lag effects\"                    # shape1-spacing-effect-lookup
time memoria ask --workspace \"\$VAULT\" --json \\
  --question \"when do desirable difficulties reverse for high element interactivity material\" # shape1-undesirable-difficulty-boundary
time memoria explore --workspace \"\$VAULT\" \"testing effect boundary conditions\" --depth 1 --json  # shape2-testing-effect-tension
time memoria project explore --workspace \"\$VAULT\" --limit 10 --json                           # not a fixture row: project-surface probe
memoria attention list --workspace \"\$VAULT\" --json | tee stage1-attention.json
memoria attention worklist --workspace \"\$VAULT\" --json | tee stage1-worklist.json
sqlite3 \"\$DB\" \"SELECT COUNT(*) FROM event_log;\" \\
  | xargs -I{} echo \"stage1_event_log_rows={}\" | tee -a staged-import-metrics.txt
du -sh \"\$VAULT/.memoria\" | tee -a staged-import-metrics.txt"
  say "Record Shape-1 ask and Shape-2 explore latencies separately. More than 200 ms interactive triggers the substrate re-comparison early; record it either way."
  record "Stage 1 retrieval, attention/worklist, event-log, and database-size evidence"

  stage "Triage every Stage 1 attention item"
  step "Start a human wall clock and inspect every row in the one run-scoped worklist. For each item, you—not the wizard—select apply, reject, or defer and author the reason."
  show_command "memoria attention resolve --workspace \"\$VAULT\" <attention_path> --apply|--reject|--defer --reason \"<why>\""
  say "Record attention-item count, triage minutes, every selected disposition and reason, and whether the bounded batch fit within 60 minutes. The wizard will never select a disposition."
  record "Stage 1 PI triage of every attention item"

  stage "Prove disposition instrumentation"
  step "Query the authoritative event_log plane after triage. The count must be at least one, and you must inspect at least one disposition row whose item_id matches an attention path you just resolved."
  show_command "sqlite3 \"\$VAULT/.memoria/memoria.sqlite\" \\
  \"SELECT COUNT(*) FROM event_log WHERE event_type='disposition';\"   # must be >= 1"
  if confirm "Did the count exceed zero and did a disposition item_id match your resolved attention path?"; then
    LOOP13_STAGE2_ALLOWED=true
    record "Disposition instrumentation proof"
  else
    warn "Zero dispositions or no matching item is a hard result: record it, stop the protocol, and do not proceed to Stage 2."
    printf '  %sSTOP:%s Stage 2 is not licensed by this run.\n' "$RED" "$RESET"
    record "Disposition instrumentation failure"
  fi

  stage "Make the explicit staged-import stop decision"
  step "Read the dashboard and decide yourself whether triage volume, rebuild/query latency, a provider-policy prompt, or any other observation broke the session's flow. A manual rule does not fire automatically, and the wizard will not make this judgment."
  show_command "memoria dashboard --workspace \"\$VAULT\" --json"
  if confirm "Did you observe a staged-import stop condition?"; then
    LOOP13_STAGE2_ALLOWED=false
    warn "Record the observation before changing status. The observation IS the finding."
    say "Do not hand-write \$VAULT/.memoria/config/decision-rules.yaml; a one-entry file replaces the shipped registry."
    show_command "python -c \"from pathlib import Path; from memoria_vault.runtime.decision_rules import update_rule_status; \\
update_rule_status(Path('\$VAULT'), 'staged-import', 'fired')\""
    record "Staged-import stop observation and PI status update"
  else
    say "No rule action is needed. Record the no-stop decision; do not fire or retire a rule speculatively."
    record "Staged-import no-stop decision"
  fi

  stage "Conditionally repeat at 100 works"
  if [[ "$LOOP13_STAGE2_ALLOWED" == true ]] && confirm "Proceed with the 100-work stage after reviewing Stage 1 evidence?"; then
    step "Only now repeat the whole Stage 1 import, drain, retrieval, attention, PI triage, instrumentation, and stop-review block with stage2.bib. Take a fresh BEFORE watermark."
    step "Use the exact Stage 1 commands and frozen fixture arguments already reviewed, making only the plan-prescribed stage/file substitutions; the plan does not supply additional fixture fields or command arguments to invent."
    say "Stop at any stage where triage volume, rebuild/query latency, or provider policy breaks the session. Record the stop reason instead of pushing through."
    record "Stage 2 100-work repeat"
  else
    say "Stage 2 is blocked or declined. It runs only after Stage 1's instrumentation proof and no stop decision. Record the reason; do not push through."
    record "Stage 2 not run"
  fi

  stage "Rehearse the Phase 2 loop"
  show_command "memoria status --workspace \"\$VAULT\""
  step "Run one memoria project ask or memoria project gaps command against the framed live project. The plan does not prescribe its project identifiers or arguments; inspect the live project and CLI help rather than guessing."
  show_command "memoria list --workspace \"\$VAULT\" --type work"
  step "Confirm the admitted catalog is enumerated and record the status, project result, gaps or answer evidence, and catalog evidence."
  record "Phase 2 rehearsal"

  stage "Author and review the LOOP.13 acceptance record"
  step "Write docs/superpowers/specs/\$(date +%F)-staged-import-acceptance-run.md yourself. Include: vault freshness and never-test-vault attestation; licensed stage1.bib and stage2.bib provenance; seeded-error verdict; time_to_first_answer_s and the 1800-second bar; frozen fixture id, exact query/topic, declared depth, metric, and separate Shape-1 ask and Shape-2 explore latencies against 200 ms; each stage's import wall-clock and complete import-run.v1 row; enrichment drain result, provider-policy prompts, and per-stage retraction delta; attention items per 100 works, worklist evidence, triage minutes, every PI disposition and reason, and whether the batch fit within 60 minutes; event-log count, database-size evidence, disposition count greater than zero, and a matching item_id proof; every stop-rule observation, decision, status update, and stop reason; whether Stage 2 ran; and Phase 2 status, project, and catalog evidence."
  step "Review the resulting artifact for accuracy and secrets. A failed seeded-error verdict, zero disposition count, stop-rule observation, provider-policy prompt, or latency that broke session flow remains a recorded result and may block acceptance; never rewrite it as a pass."
  say "The PI may commit only after writing and reviewing the resulting artifact. The commit is optional."
  show_command "git add docs/superpowers/specs/\$(date +%F)-staged-import-acceptance-run.md
git commit -m \"docs(specs): staged 10->100 import acceptance run — recorded metrics

Co-Authored-By: Claude Fable 5 <noreply@anthropic.com>\""
  record "PI-authored staged-import-acceptance-run.md review and optional commit"
fi

if [[ "$SECTION" == "all" || "$SECTION" == "plugin" || "$SECTION" == "canvas" ]]; then
  say "Review the private temporary run log at $RUN_LOG."
  say "Transfer plugin and Canvas pass, fail, blocked, and skipped outcomes to the relevant PR description."
  say "The temporary log is working evidence, not the acceptance artifact."
fi
